// Test implementation of CalculateSharedPrefix
size_t CalculateSharedPrefix(const Slice& a, const Slice& b) {
    const size_t len = std::min(a.size(), b.size());
    size_t i = 0;
    while (i < len && a.data()[i] == b.data()[i]) {
        i++;
    }
    return i;
}

// Test cases
void test() {
    // Test 1: Empty slices
    Slice e1, e2;
    assert(CalculateSharedPrefix(e1, e2) == 0);

    // Test 2: One empty, one non-empty
    Slice empty, non_empty("abc");
    assert(CalculateSharedPrefix(empty, non_empty) == 0);
    assert(CalculateSharedPrefix(non_empty, empty) == 0);

    // Test 3: Identical slices
    Slice s1("hello"), s2("hello");
    assert(CalculateSharedPrefix(s1, s2) == 5);

    // Test 4: One is prefix of other
    Slice prefix("abc"), longer("abcdef");
    assert(CalculateSharedPrefix(prefix, longer) == 3);
    assert(CalculateSharedPrefix(longer, prefix) == 3);

    // Test 5: No common prefix
    Slice a("xyz"), b("abc");
    assert(CalculateSharedPrefix(a, b) == 0);

    // Test 6: Partial common prefix
    Slice c("foobar"), d("foolish");
    assert(CalculateSharedPrefix(c, d) == 3);  // "foo"

    // Test 7: Single byte match
    Slice x("a"), y("ab");
    assert(CalculateSharedPrefix(x, y) == 1);

    // Test 8: Single byte no match
    Slice p("x"), q("y");
    assert(CalculateSharedPrefix(p, q) == 0);
}

